set-var "lrn-id" get-val-public "itemId"
learnosity items [
  item metadata [
    tags {
      CCSS: "HS-LS1-7"
      DOK: 2
      Difficulty: "medium"
    }
  ] questions [
    mcq stimulus "Which organelle is the site of aerobic respiration?"
      options [
        "Mitochondrion"
        "Chloroplast"
        "Ribosome"
        "Nucleus"
      ] valid-response [
      0
    ] metadata [
      distractor-rationale [
        "Correct — the mitochondrion is where aerobic respiration occurs."
        "Chloroplasts are the site of photosynthesis, not aerobic respiration. They capture light energy, while mitochondria release chemical energy from glucose."
        "Ribosomes are the site of protein synthesis. They translate mRNA into proteins but do not participate in aerobic respiration."
        "The nucleus stores and protects genetic material and controls cell activities, but aerobic respiration occurs in the mitochondrion, not the nucleus."
      ]
    ] {}
  ] {}
] {}..

